  inList(testValue, compareList) {
    return compareList.indexOf(testValue) > -1;
  }
  // Converts Camel Case strings to words
  camelWords(camelString) {
    let wordString = camelString.replace(/[A-Z]/g, s => {
      return ' ' + s;
    });
    wordString = wordString.charAt(0).toUpperCase() + wordString.slice(1);
    return wordString;
  }
  // Converts hex string to ASCII string
  hexToAscii(hexString) {
    var str = '';
    for (var n = 0; n < hexString.length; n += 2) {
      str += String.fromCharCode(parseInt(hexString.substr(n, 2), 16));
    }
    return str;
  }
  // Converts ASCII string to hex string
  asciiToHex(asciiString) {
    const hexArray = [];
    for (var n = 0, l = asciiString.length; n < l; n++) {
      const hex = Number(asciiString.charCodeAt(n)).toString(16);
      hexArray.push(hex);
    }
    return hexArray.join('');
  }
  // Generate a distinct list of values
  distinct(arr, ...keys) {
    const key = obj => JSON.stringify(keys.map(k => obj[k]));
    const val = obj => keys.reduce((a, k) => (a[k] = obj[k], a), {});
    const dict = arr.reduce((a, t) => (a[key(t)] = val(t), a), {});
    return Object.values(dict);
  }
  // Encode a Base 64 string
  encodeBase64(data) {
    return window.btoa(data);
  }
  // Decode a Base 64 string
  decodeBase64(data) {
    return window.atob(data);
  }
