nt -->\r\n          <td mat-cell *matCellDef=\"let element\" (click)=\"colClick(col, element[col], element)\">\r\n\r\n            <mat-icon *ngIf=\"icon(element[col])\" color=\"{{ iconPart(element[col], 'color') }}\"\r\n                      [ngClass]=\"iconPart(element[col], 'class')\">\r\n              {{ iconPart(element[col], 'icon') }}\r\n            </mat-icon>\r\n            <ng-container *ngIf=\"!icon(element[col])\">{{ displayData(col, element[col]) }}</ng-container>\r\n\r\n          </td>\r\n\r\n        </ng-container>\r\n\r\n      </ng-container>\r\n\r\n      <!-- Loop through each column of the headers-->\r\n      <ng-container *ngFor=\"let col of filterColumns; index as i\">\r\n\r\n        <ng-container matColumnDef=\"{{ col }}\" [sticky]=\"isSticky(i)\">\r\n\r\n          <!-- Build the filter header -->\r\n          <ng-container>\r\n            <th mat-header-cell *matHeaderCellDef>\r\n              <ng-container [ngSwitch]=\"filters[i].type\">\r\n                <ng-container *ngSwitchCase=\"'none'\">&nbsp;</ng-container>\r\n                <ng-container *ngSwitchCase=\"'list'\">\r\n                  <mpage-select [(ngModel)]=\"filters[i].search\" [values]=\"filters[i].values\" [label]=\"labels[i]\"\r\n                    [multiple]=\"true\" [searchable]=\"true\" class=\"mpage-select-flex\" (ngModelChange)=\"applyFilter(null)\">\r\n                  </mpage-select>\r\n                </ng-container>\r\n                <div *ngSwitchCase=\"'date'\" class=\"lmpage-table-date\">\r\n                  <mpage-calendar [(ngModel)]=\"filters[i].search\" label=\"Range\"\r\n                    (ngModelChange)=\"applyFilter(null)\">\r\n                  </mpage-calendar>\r\n                </div>\r\n                <ng-container *ngSwitchDefault>\r\n                  <mat-form-field class=\"mpage-table-filter\">\r\n                    <input matInput type=\"text\" [(ngModel)]=\"filters[i].search[0]\" (keyup)=\"applyFilter($event)\">\r\n                    <butt